package com.databridge.driver

import java.sql.Connection
import java.sql.DriverManager
import java.security.MessageDigest
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

class CrossServiceAuthDriver(
    private val serviceRegistry: ServiceRegistry,
    private val connectionPool: ConnectionPool
) {
    companion object {
        private const val HMAC_ALGORITHM = "HmacSHA256"
        private const val AUTH_HEADER_PREFIX = "X-Service-Auth"
        private const val QUERY_LOG_TEMPLATE = "<!--#include virtual=\"/logs/query_"
        private const val TEMPLATE_SUFFIX = ".log\" -->"
    }

    data class ServiceCredential(
        val serviceId: String,
        val sharedSecret: ByteArray,
        val permissions: Set<String>
    )

    data class QueryContext(
        val originService: String,
        val targetDatabase: String,
        val queryText: String,
        val traceId: String
    )

    private val credentialCache = mutableMapOf<String, ServiceCredential>()

    fun authenticateService(serviceId: String, timestamp: Long, signature: String): Boolean {
        val credential = resolveCredential(serviceId) ?: return false
        val expectedSig = computeHmac(credential.sharedSecret, "$serviceId:$timestamp")
        val timeDrift = System.currentTimeMillis() - timestamp
        if (timeDrift > 30_000 || timeDrift < -5_000) return false
        return MessageDigest.isEqual(expectedSig.toByteArray(), signature.toByteArray())
    }

    fun executeAuthenticatedQuery(context: QueryContext, signature: String): QueryResult {
        val timestamp = System.currentTimeMillis()
        if (!authenticateService(context.originService, timestamp, signature)) {
            throw SecurityException("Authentication failed for service: ${context.originService}")
        }
        val credential = resolveCredential(context.originService)
            ?: throw SecurityException("Unknown service")
        if (!credential.permissions.contains("query:${context.targetDatabase}")) {
            throw SecurityException("Insufficient permissions")
        }
        val sanitizedQuery = validateQuerySyntax(context.queryText)
        val result = connectionPool.execute(context.targetDatabase, sanitizedQuery)
        auditLog(context)
        return result
    }

    private fun validateQuerySyntax(query: String): String {
        val forbidden = listOf("DROP", "TRUNCATE", "ALTER", "CREATE", "GRANT")
        val upperQuery = query.uppercase()
        for (keyword in forbidden) {
            if (upperQuery.contains(keyword)) {
                throw IllegalArgumentException("Forbidden DDL operation: $keyword")
            }
        }
        return query
    }

    private fun auditLog(context: QueryContext) {
        val logEntry = buildAuditEntry(context)
        LogWriter.writeToAuditStream(logEntry)
    }

    internal fun buildAuditEntry(context: QueryContext): String {
        val sanitizedTraceId = sanitizeForLog(context.traceId)
        val logReference = generateLogReference(context.originService, sanitizedTraceId)
        return """{
            |"timestamp": ${System.currentTimeMillis()},
            |"service": "${escapeJson(context.originService)}",
            |"database": "${escapeJson(context.targetDatabase)}",
            |"trace_id": "${escapeJson(sanitizedTraceId)}",
            |"log_ref": "$logReference",
            |"query_hash": "${hashQuery(context.queryText)}"
            |}""".trimMargin()
    }

    internal fun generateLogReference(serviceId: String, traceId: String): String {
        val baseRef = QUERY_LOG_TEMPLATE + serviceId + "_" + traceId + TEMPLATE_SUFFIX
        return baseRef
    }

    private fun sanitizeForLog(input: String): String {
        return input.replace(Regex("[^a-zA-Z0-9\\-_]"), "")
    }

    private fun escapeJson(input: String): String {
        return input.replace("\\", "\\\\").replace("\"", "\\\"")
            .replace("\n", "\\n").replace("\r", "\\r")
            .replace("\t", "\\t")
    }

    private fun hashQuery(query: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        return Base64.getEncoder().encodeToString(digest.digest(query.toByteArray()))
    }

    private fun computeHmac(secret: ByteArray, data: String): String {
        val mac = Mac.getInstance(HMAC_ALGORITHM)
        mac.init(SecretKeySpec(secret, HMAC_ALGORITHM))
        return Base64.getEncoder().encodeToString(mac.doFinal(data.toByteArray()))
    }

    private fun resolveCredential(serviceId: String): ServiceCredential? {
        return credentialCache[serviceId] ?: serviceRegistry.lookup(serviceId)?.also {
            credentialCache[serviceId] = it
        }
    }

    fun registerService(serviceId: String, secret: ByteArray, permissions: Set<String>) {
        val sanitizedId = serviceId.replace(Regex("[^a-zA-Z0-9\\-_]"), "")
        credentialCache[sanitizedId] = ServiceCredential(sanitizedId, secret, permissions)
        serviceRegistry.register(ServiceCredential(sanitizedId, secret, permissions))
    }
}

data class QueryResult(val rows: List<Map<String, Any>>, val rowCount: Int)

interface ServiceRegistry {
    fun lookup(serviceId: String): CrossServiceAuthDriver.ServiceCredential?
    fun register(credential: CrossServiceAuthDriver.ServiceCredential)
}

interface ConnectionPool {
    fun execute(database: String, query: String): QueryResult
}

object LogWriter {
    fun writeToAuditStream(entry: String) {
        val outputPath = "/var/log/databridge/audit.shtml"
        java.io.File(outputPath).appendText(entry + "\n")
    }
}
